import React from 'react';
import { render, screen } from '@testing-library/react';
import Avatar from './Avatar';
import { formatInitials } from './utils/formatInitials';
import { generateRandomColors } from './utils/generateRandomColors';

describe('Avatar', () => {
  test('should render with initials', () => {
    render(<Avatar variantType="initials">{formatInitials('Admin Portal')}</Avatar>);
    expect(screen.getByText('AP')).toBeInTheDocument();
  });

  test('should render with one initial when one name is sent as argument', () => {
    render(<Avatar variantType="initials">{formatInitials('Admin')}</Avatar>);
    expect(screen.getByText('A')).toBeInTheDocument();
  });

  test('should render empty without crashing', () => {
    const name = null;
    render(<Avatar variantType="initials">{formatInitials(name)}</Avatar>);
    expect(screen.getByTestId('adminPortalAvatar')).toBeInTheDocument();
  });

  test('should render with generateRandomColor method without crashing', () => {
    const name = 'Admin Portal';
    render(
      <Avatar variantType="initials" background={generateRandomColors()}>
        {formatInitials(name)}
      </Avatar>
    );
    expect(screen.getByTestId('adminPortalAvatar')).toBeInTheDocument();
  });

  test('should render with image without crashing', () => {
    const imgUrl =
      'https://admin-portal.bees-platform.com/mf/admin-portal-frame-mfe/5253bdf8773135cf239a58c986aa8a5b.svg';
    render(<Avatar variantType="image" image={imgUrl} />);
    expect(screen.getByTestId('adminPortalAvatar')).toBeInTheDocument();
  });
});
